module Rails
  class Application
    class ReloadersCollection
      include Enumerable

      def initialize
        @reloaders = []
      end

      def <<(reloader)
        @reloaders << reloader
        self
      end

      def each(&block)
        @reloaders.each(&block)
      end

      def delete(reloader)
        @reloaders.delete(reloader)
        reloader.deactivate if reloader.respond_to?(:deactivate)
        reloader
      end

      def clear
        @reloaders.each do |reloader|
          reloader.deactivate if reloader.respond_to?(:deactivate)
        end
        @reloaders.clear
      end
    end
  end
end
